"""GSM8K environment.

Single-turn grade-school math environment over the GSM8K dataset. The model
reasons inside <think>...</think> tags and gives a final numeric answer; the
rubric rewards an exact numeric match against the gold answer.
"""

SYSTEM_PROMPT = (
    "Think step by step inside <think>...</think> tags, then give your "
    "final numeric answer inside <answer>...</answer> tags."
)


def _extract_answer(solution: str) -> str:
    if "####" not in solution:
        return solution.strip()
    return solution.split("####")[-1].strip().replace(",", "").replace("$", "")


def load_environment(
    dataset_name: str = "openai/gsm8k",
    config: str = "main",
    split: str = "train",
    **kwargs,
):
    from datasets import load_dataset

    from verifiers import Rubric, SingleTurnEnv, ThinkParser

    dataset = load_dataset(dataset_name, config, split=split)
    dataset = dataset.map(
        lambda x: {"question": x["question"], "answer": _extract_answer(x["answer"])}
    )

    parser = ThinkParser()

    def correct_answer(completion, answer, **kwargs) -> float:
        response = (parser.parse_answer(completion) or "").strip()
        response = response.replace(",", "").replace("$", "")
        try:
            return 1.0 if float(response) == float(str(answer).strip()) else 0.0
        except ValueError:
            return 0.0

    rubric = Rubric(funcs=[correct_answer], weights=[1.0], parser=parser)

    return SingleTurnEnv(
        dataset=dataset,
        system_prompt=SYSTEM_PROMPT,
        parser=parser,
        rubric=rubric,
        **kwargs,
    )

