"""xLAM function-calling environment.

Tool environment over Salesforce's xLAM function-calling dataset. The
dataset (loaded lazily from the hub) provides per-example tool schemas and
queries; the model must produce a tool call matching the gold call. Tools
are stub executors derived from each example's schema — this environment
evaluates tool-call *selection and arguments*, not real execution.
"""

import ast
import json

SYSTEM_PROMPT = (
    "You are a function-calling assistant. Given the user's request, call "
    "the appropriate tool with the correct arguments."
)


def _safe_literal_list(value):
    """Parse a value that may be a JSON/Python-literal list string."""
    if isinstance(value, list):
        return value
    try:
        return json.loads(value)
    except (json.JSONDecodeError, TypeError):
        return ast.literal_eval(value)


def _make_stub_tool(tool_spec: dict):
    """Build a stub executor function from an xLAM tool schema."""
    name = tool_spec.get("name", "tool")
    params = (tool_spec.get("parameters") or {}).get("properties", {})
    description = tool_spec.get("description", f"Stub for the {name} tool.")

    def stub(**kwargs) -> str:
        return json.dumps({"tool": name, "received": kwargs})

    stub.__name__ = name
    stub.__doc__ = description + "\n\nArgs:\n" + "\n".join(
        f"    {p}: {spec.get('description', '')}" for p, spec in params.items()
    )
    return stub


def load_environment(
    dataset_name: str = "Salesforce/xlam-function-calling-60k",
    split: str = "train",
    num_examples: int = 100,
    **kwargs,
):
    from datasets import load_dataset

    from verifiers import Rubric, ToolEnv, XMLParser

    try:
        raw = load_dataset(dataset_name, split=split)
    except Exception as e:
        raise RuntimeError(
            f"Failed to load {dataset_name!r}. The dataset is gated — run "
            "`huggingface-cli login` and accept the terms at "
            "https://huggingface.co/datasets/Salesforce/xlam-function-calling-60k "
            "first."
        ) from e

    raw = raw.shuffle(seed=42).select(range(min(num_examples, len(raw))))

    rows = []
    for row in raw:
        tools = _safe_literal_list(row["tools"])
        answers = _safe_literal_list(row["answers"])
        if not tools or not answers:
            continue
        rows.append(
            {
                "question": row["query"],
                "answer": json.dumps(answers[0]),
                "info": {"tools": tools},
            }
        )

    from datasets import Dataset

    dataset = Dataset.from_list(rows)

    parser = XMLParser(fields=["tool", "answer"])

    def correct_tool_name(completion, answer, **kwargs) -> float:
        try:
            gold = json.loads(answer)
        except (json.JSONDecodeError, TypeError):
            return 0.0
        text = completion if isinstance(completion, str) else str(completion)
        gold_name = gold.get("name", "")
        return 1.0 if gold_name and gold_name in text else 0.0

    def has_tool_call(state, **kwargs) -> float:
        return 1.0 if len(state.get("steps", [])) > 0 else 0.0

    rubric = Rubric(
        funcs=[correct_tool_name, has_tool_call],
        weights=[0.8, 0.2],
        parser=parser,
    )

    return ToolEnv(
        dataset=dataset,
        tools=[],
        system_prompt=SYSTEM_PROMPT,
        parser=parser,
        rubric=rubric,
        max_turns=4,
        **kwargs,
    )

